-- IronGate QA Navigator data snapshot (converted from MySQL by scripts/mysql-to-postgres.ts)
-- Load AFTER the schema migration: psql "$DATABASE_URL" -f db_snapshots/latest_snapshot.postgres.sql

BEGIN;
-- Skip FK checks and updated_at triggers while loading, like mysqldump's FOREIGN_KEY_CHECKS=0
SET LOCAL session_replication_role = replica;
































































-- Move identity sequences past the imported ids
SELECT setval(pg_get_serial_sequence('"company_kpi_snapshots"', 'id'), COALESCE((SELECT MAX("id") FROM "company_kpi_snapshots"), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('"developer_productivity_snapshots"', 'id'), COALESCE((SELECT MAX("id") FROM "developer_productivity_snapshots"), 0) + 1, false);

COMMIT;
